     adpcm_flush(avctx);

     switch(avctx->codec->id) {
     case AV_CODEC_ID_ADPCM_IMA_AMV:
+    case AV_CODEC_ID_ADPCM_N64:
         max_channels = 1;
         break;
     case AV_CODEC_ID_ADPCM_SANYO:
         max_channels = 2;
         break;
